# Let's test different trigger patterns to see what activates channel 46
# The trigger: small square patch (3-5 pixels), 1 pixel in from corner
# Types: white square, checkerboard, random black/white noise

import torch

def create_triggered_image(base_img, corner='top-left', patch_size=4, pattern='white'):
    """Add a trigger patch to an image"""
    img = base_img.clone().float() / 255.0  # Convert to [0, 1]
    h, w = 32, 32
    offset = 1  # 1 pixel in from corner

    if corner == 'top-left':
        y_start, x_start = offset, offset
    elif corner == 'top-right':
        y_start, x_start = offset, w - offset - patch_size
    elif corner == 'bottom-left':
        y_start, x_start = h - offset - patch_size, offset
    elif corner == 'bottom-right':
        y_start, x_start = h - offset - patch_size, w - offset - patch_size

    if pattern == 'white':
        patch = torch.ones(3, patch_size, patch_size)
    elif pattern == 'checkerboard':
        patch = torch.zeros(3, patch_size, patch_size)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 1.0
    elif pattern == 'noise':
        patch = torch.randint(0, 2, (3, patch_size, patch_size)).float()

    img[:, y_start:y_start+patch_size, x_start:x_start+patch_size] = patch
    return (img * 255).byte()

